card.icon:
[[[
  /* mdi:garage is the old default - treat it as 'auto' */
  const ic = variables.icon;
  if (ic && ic !== 'mdi:garage') return ic;
  const s = entity.state;
  const veh = variables.vehicle_entity && states[variables.vehicle_entity]?.state === 'on';
  if (s === 'opening') return 'mdi:garage-open';
  if (s === 'closing') return 'mdi:garage';
  if (s !== 'closed')  return veh ? 'mdi:garage-open-variant' : 'mdi:garage-open';
  return veh ? 'mdi:garage-variant' : 'mdi:garage';
]]]

tap_action.service:
[[[
  const t = variables.toggle_button;
  if (!t) return 'cover.toggle';
  const d = t.split('.')[0];
  if (d === 'button') return 'button.press';
  if (d === 'script') return 'script.turn_on';
  return d + '.toggle';
]]]

card.background:
[[[
  const st = entity.state;
                    if (st === 'opening' || st === 'closing') return 'rgba(255,152,0,0.22)';
                    const m = variables.alert_mode;
  const bad = m === 'open' ? entity.state !== 'closed' : entity.state === 'Violated';
  const veh = variables.vehicle_entity && states[variables.vehicle_entity]?.state === 'on';
  if (bad) return 'rgba(244,67,54,0.20)';
  if (veh) return 'rgba(76,175,80,0.20)';
  return 'rgba(255,255,255,0.12)';
]]]

