icon.animation:
[[[
  const s = entity.state;
  return (s === 'opening' || s === 'closing')
    ? 'charro-door-move 1.1s ease-in-out infinite' : 'none';
]]]

card_mod.style:
@keyframes charro-door-move { 0%,100% { opacity: 1; } 50% { opacity: 0.25; } }
ha-card, ha-card:hover {
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  box-shadow: none !important;
  border: none !important;
}
ha-card::before, ha-card::after { display: none !important; }

custom_fields.s:
[[[
  const st = entity.state.charAt(0).toUpperCase() + entity.state.slice(1);
  const secs = (Date.now() - new Date(entity.last_changed).getTime()) / 1000;
  const m = Math.floor(secs / 60), h = Math.floor(m / 60), d = Math.floor(h / 24);
  let ago;
  if (d > 0) ago = `${d} day${d > 1 ? 's' : ''} ago`;
  else if (h > 0) ago = `${h} hour${h > 1 ? 's' : ''} ago`;
  else if (m > 0) ago = `${m} minute${m > 1 ? 's' : ''} ago`;
  else ago = 'just now';
  return `${st} · ${ago}`;
]]]
